#!/bin/sh
# Runs the ported ansible role system (ansible/_org/roles/system) locally.
# Generated by generate.py from ansible/; do not edit.
set -eu
export DEBIAN_FRONTEND=noninteractive
WORK=/opt/imagebuilder/ansible
install -d -m 0755 "$WORK/roles/system/tasks" "$WORK/roles/system/defaults" "$WORK/roles/system/templates"
cat > "$WORK/local.yml" <<'IMAGEBUILDER_ROLE_EOF'
---
# Port of ansible/_org/local.yml. The original pre_tasks installed Docker from
# the CentOS repository with yum; the Ubuntu image does not install Docker
# (container runtimes are removed by 80-remove-containers.sh).
- name: Hardening of the Ubuntu 26.04 golden image
  hosts: localhost
  connection: local
  become: false
  gather_facts: true
  roles:
    - system
IMAGEBUILDER_ROLE_EOF
cat > "$WORK/roles/system/defaults/main.yml" <<'IMAGEBUILDER_ROLE_EOF'
---
# Port of roles/system/defaults/main.yml (fci-dt/ubuntu-2204), adapted to
# Ubuntu 26.04. Deviations from the RHEL/CentOS original are marked.

kernel_hardening_conf:
  - cramfs
  - freevxfs
  - jffs2
  - hfs
  - hfsplus
  # squashfs, fat and vfat are NOT disabled on Ubuntu: snapd needs squashfs and
  # the cloud image mounts its EFI system partition (vfat) from fstab; blocking
  # them makes the image fail to boot to a normal target.
  - udf
  - cifs
  - nfs
  - nfsv3
  - nfsv4
  - gfs2
  - usb-storage
  - bnep
  - bluetooth
  - btusb
  - net-pf-31
  - appletalk
  - dccp
  - sctp
  - rds
  - tipc

limits_conf: []

# Original: adm, ftp, games, lp. adm is kept: on Ubuntu it is the group that
# owns /var/log files and removing it breaks log access. ftp does not exist.
removal_of_users:
  - games
  - lp

removal_of_groups:
  - games

# Ubuntu equivalents of the CentOS package list. Not ported: parted (needed by
# cloud-init disk growing tooling), linux-firmware (pulled in by kernel
# metapackages), m4/jansson/snappy/GeoIP/centos-logos (no Ubuntu counterpart).
removal_of_packages:
  - xinetd
  - telnet
  - rsh-client
  - rsh-server
  - nis
  - tftpd-hpa
  - bind9
  - vsftpd
  - dovecot-core
  - squid
  - snmpd
  - talk
  - talkd
  - postfix
  - wpasupplicant
  - avahi-daemon

# Packages whose removal must abort the hardening instead.
removal_protected_packages:
  - cloud-init
  - openssh-server
  - open-vm-tools
  - netplan.io
  - systemd
  - linux-image

# psacct (RHEL) is acct on Debian/Ubuntu.
installing_of_packages:
  - acct

# CentOS service names that exist on Ubuntu under another name or not at all
# are mapped or dropped. messagebus (dbus) is NOT disabled: systemd-logind and
# VMware Tools need it.
disable_of_services:
  - xinetd
  - rsh.socket
  - rlogin.socket
  - rexec.socket
  - ypbind
  - tftpd-hpa
  - kdump-tools
  - mdmonitor
  - ntpdate
  - bind9
  - apache2
  - dovecot
  - squid
  - snmpd
  - atd
  - smartmontools
  - rpcbind

enable_of_services:
  - irqbalance
  - acct
  - cron
  - cloud-init-local
  - cloud-init
  - cloud-config
  - cloud-final

# Kept from the original; ip_forward is needed by container hosts.
sysctl_ip_forward: 1
sysctl_disable_ipv6: 1
session_timeout_seconds: 900
IMAGEBUILDER_ROLE_EOF
cat > "$WORK/roles/system/tasks/main.yml" <<'IMAGEBUILDER_ROLE_EOF'
---
# Port of roles/system/tasks/main.yml (fci-dt/ubuntu-2204): yum -> apt,
# /etc/sysctl.conf and limits.conf replaced by drop-ins, PAM and profile edits
# moved to the locations Ubuntu regenerates from.

- name: Restrict dynamic mounting and unmounting of filesystems
  ansible.builtin.template:
    src: hardening.conf.j2
    dest: /etc/modprobe.d/hardening.conf
    mode: "0644"

- name: Kernel parameters
  ansible.builtin.template:
    src: sysctl.conf.j2
    dest: /etc/sysctl.d/99-imagebuilder-hardening.conf
    mode: "0644"

- name: Apply kernel parameters
  ansible.builtin.command: sysctl --system
  changed_when: false
  failed_when: false

- name: Set security limits to prevent DoS
  ansible.builtin.template:
    src: limits.conf.j2
    dest: /etc/security/limits.d/99-imagebuilder-hardening.conf
    mode: "0644"

- name: Removal of not needed accounts
  ansible.builtin.user:
    name: "{{ item }}"
    state: absent
  loop: "{{ removal_of_users }}"

- name: Removal of not needed groups
  ansible.builtin.group:
    name: "{{ item }}"
    state: absent
  loop: "{{ removal_of_groups }}"

- name: Check whether pam-auth-update manages unix authentication
  ansible.builtin.stat:
    path: /usr/share/pam-configs/unix
  register: pam_unix_config

- name: Remove nullok from the PAM unix profile
  ansible.builtin.replace:
    path: /usr/share/pam-configs/unix
    regexp: '\s+nullok(_secure)?\b'
    replace: ''
  when: pam_unix_config.stat.exists
  register: pam_unix_changed

- name: Regenerate PAM configuration
  ansible.builtin.command: pam-auth-update --package --force
  environment:
    DEBIAN_FRONTEND: noninteractive
  when: pam_unix_config.stat.exists and pam_unix_changed.changed

- name: Set interactive session timeout
  ansible.builtin.copy:
    dest: /etc/profile.d/99-imagebuilder-tmout.sh
    content: |
      # Interactive session timeout (imagebuilder hardening)
      readonly TMOUT={{ session_timeout_seconds }}
      export TMOUT
    mode: "0644"

- name: Simulate removal of packages
  ansible.builtin.command: "apt-get -s purge {{ removal_of_packages | join(' ') }}"
  register: removal_simulation
  changed_when: false
  failed_when: false

- name: Refuse removals that would take protected packages with them
  ansible.builtin.assert:
    that:
      - not (removal_simulation.stdout is search('^Purg ' + item, multiline=True))
    fail_msg: "Removing the hardening package list would also remove {{ item }}"
  loop: "{{ removal_protected_packages }}"

- name: Removal of packages
  ansible.builtin.apt:
    name: "{{ removal_of_packages }}"
    state: absent
    purge: true
    autoremove: false

- name: Installation of packages
  ansible.builtin.apt:
    name: "{{ installing_of_packages }}"
    state: present
  failed_when: false

- name: Disable of services
  ansible.builtin.systemd:
    name: "{{ item }}"
    state: stopped
    enabled: false
  loop: "{{ disable_of_services }}"
  failed_when: false

- name: Enabling of services
  ansible.builtin.systemd:
    name: "{{ item }}"
    enabled: true
  loop: "{{ enable_of_services }}"
  failed_when: false
IMAGEBUILDER_ROLE_EOF
cat > "$WORK/roles/system/templates/hardening.conf.j2" <<'IMAGEBUILDER_ROLE_EOF'
# Restrict Dynamic Mounting and Unmounting of Filesystems

blacklist usb-storage
blacklist firewire-core

{% if kernel_hardening_conf is defined and kernel_hardening_conf is iterable %}
{% for entry in kernel_hardening_conf %}
install {{ entry }} /bin/true
{% endfor %}
{% endif %}
IMAGEBUILDER_ROLE_EOF
cat > "$WORK/roles/system/templates/sysctl.conf.j2" <<'IMAGEBUILDER_ROLE_EOF'
# Enable packet forwarding (Docker needs it)
net.ipv4.ip_forward = {{ sysctl_ip_forward }}

# Disable redirects, not a router
net.ipv4.conf.all.accept_redirects = 0
net.ipv4.conf.default.accept_redirects = 0
net.ipv4.conf.all.send_redirects = 0
net.ipv4.conf.default.send_redirects = 0
net.ipv4.conf.all.secure_redirects = 0
net.ipv4.conf.default.secure_redirects = 0
net.ipv6.conf.all.accept_redirects = 0
net.ipv6.conf.default.accept_redirects = 0

# Disable source routing
net.ipv4.conf.all.accept_source_route = 0
net.ipv4.conf.default.accept_source_route = 0
net.ipv6.conf.all.accept_source_route = 0

# Enable source validation by reversed path
net.ipv4.conf.all.rp_filter = 1
net.ipv4.conf.default.rp_filter = 1

# Log packets with impossible addresses to kernel log
net.ipv4.conf.all.log_martians = 1
net.ipv4.conf.default.log_martians = 1

# Disable ICMP broadcasts
net.ipv4.icmp_echo_ignore_broadcasts = 1

# Ignore bogus ICMP errors
net.ipv4.icmp_ignore_bogus_error_responses = 1

# Against SYN flood attacks
net.ipv4.tcp_syncookies = 1

# Turning off timestamps could improve security but degrade performance.
# TCP timestamps are used to improve performance as well as protect against
# late packets messing up your data flow. A side effect of this feature is
# that the uptime of the host can sometimes be computed.
# If you disable TCP timestamps, you should expect worse performance
# and less reliable connections.
net.ipv4.tcp_timestamps = 1

# Disable IPv6 unless required
net.ipv6.conf.lo.disable_ipv6 = {{ sysctl_disable_ipv6 }}
net.ipv6.conf.all.disable_ipv6 = {{ sysctl_disable_ipv6 }}
net.ipv6.conf.default.disable_ipv6 = {{ sysctl_disable_ipv6 }}

# Do not accept router advertisements
net.ipv6.conf.all.accept_ra = 0
net.ipv6.conf.default.accept_ra = 0

# Disable core dumps
fs.suid_dumpable = 0

# Disable System Request debugging functionality
kernel.sysrq = 0

# Restrict access to kernel logs
kernel.dmesg_restrict = 1

# Randomise memory space
kernel.randomize_va_space = 2

# Hide kernel pointers
kernel.kptr_restrict = 2
IMAGEBUILDER_ROLE_EOF
cat > "$WORK/roles/system/templates/limits.conf.j2" <<'IMAGEBUILDER_ROLE_EOF'
# 4096 is a good starting point
*      soft   nofile    4096
*      hard   nofile    65536
*      soft   nproc     4096
*      hard   nproc     4096
*      soft   locks     4096
*      hard   locks     4096
*      soft   stack     10240
*      hard   stack     32768
*      soft   memlock   64
*      hard   memlock   64
*      hard   maxlogins 10

# Soft limit 32GB, hard 64GB
*      soft   fsize     33554432
*      hard   fsize     67108864

# Limits for root
root   soft   nofile    4096
root   hard   nofile    65536
root   soft   nproc     4096
root   hard   nproc     4096
root   soft   stack     10240
root   hard   stack     32768
root   soft   fsize     33554432

{% if limits_conf is defined and limits_conf is iterable %}
{% for entry in limits_conf %}
{{ entry }}
{% endfor %}
{% endif %}
IMAGEBUILDER_ROLE_EOF
cd "$WORK"
ANSIBLE_NOCOLOR=1 ansible-playbook -i localhost, -c local local.yml
